 function renderLayers(){const panel=document.getElementById('nirmaan-layers');if(!panel)return;panel.replaceChildren();const search=(document.getElementById('nb-layer-search')?.value||'').trim().toLowerCase();const hasMatch=n=>(n.settings.label||n.type||'').toLowerCase().includes(search)||(n.children||[]).some(hasMatch);const build=(nodes,depth)=>nodes.forEach((n,index)=>{if(search&&!hasMatch(n))return;const wrap=document.createElement('div');wrap.className='nb-layer-item';wrap.draggable=!n.settings.locked;wrap.dataset.layerId=n.id;wrap.ondragstart=e=>{if(n.settings.locked){e.preventDefault();return;}e.dataTransfer.setData('text/plain',n.id);e.dataTransfer.effectAllowed='move';};wrap.ondragover=e=>{e.preventDefault();wrap.classList.add('nb-layer-drop-target');};wrap.ondragleave=()=>wrap.classList.remove('nb-layer-drop-target');wrap.ondrop=e=>{e.preventDefault();e.stopPropagation();wrap.classList.remove('nb-layer-drop-target');const source=find(e.dataTransfer.getData('text/plain')),target=find(n.id);if(!source||!target||source.node.id===target.node.id||source.node.settings.locked||containsId(source.node,target.node.id))return;checkpoint();const moving=source.nodes.splice(source.index,1)[0];const refreshed=find(n.id);if(refreshed.node.children&&['section','fullwidth_section','specialty_section','row','column','container','columns'].includes(refreshed.node.type))refreshed.node.children.push(moving);else{const latest=find(n.id);latest.nodes.splice(latest.index+(e.offsetY>wrap.offsetHeight/2?1:0),0,moving);}selectNode(moving.id);render();markChanged('Layer moved');};const row=document.createElement('div');row.className='nb-layer-row-wrap';row.style.paddingLeft=(depth*14)+'px';if(n.children){const toggle=document.createElement('button');toggle.type='button';toggle.className='nb-layer-mini';toggle.textContent=collapsedLayers.has(n.id)&&!search?'+':'−';toggle.setAttribute('aria-label',collapsedLayers.has(n.id)?'Expand layer':'Collapse layer');toggle.onclick=()=>{collapsedLayers.has(n.id)?collapsedLayers.delete(n.id):collapsedLayers.add(n.id);renderLayers();};row.appendChild(toggle);}const select=document.createElement('button');select.type='button';select.className='nb-layer-row'+(selectedIds.has(n.id)?' is-selected':'');select.textContent=(n.settings.label||n.type||'Element')+(n.settings.hidden?' (hidden)':'')+(n.settings.locked?' (locked)':'');select.setAttribute('aria-current',selected===n.id?'true':'false');select.onclick=e=>{selectNode(n.id,e.ctrlKey||e.metaKey);render();};row.appendChild(select);const action=(text,title,fn,disabled=false)=>{const b=document.createElement('button');b.type='button';b.className='nb-layer-mini';b.textContent=text;b.title=title;b.setAttribute('aria-label',title);b.disabled=disabled;b.onclick=fn;row.appendChild(b);};action('↑','Move layer up',()=>moveLayer(n.id,'up'),index===0);action('↓','Move layer down',()=>moveLayer(n.id,'down'),index===nodes.length-1);action('⇥','Indent into previous layout',()=>moveLayer(n.id,'indent'),index===0||!nodes[index-1]?.children);action('⇤','Outdent layer',()=>moveLayer(n.id,'outdent'),!find(n.id)?.parent);action('✎','Rename layer',()=>{const name=prompt('Layer name:',n.settings.label||n.type);if(name&&name.trim()){checkpoint();n.settings.label=name.trim().slice(0,80);renderLayers();renderLayerNavigator();markChanged('Layer renamed');}});action(n.settings.hidden?'Show':'Hide','Toggle visibility',()=>{checkpoint();n.settings.hidden=!n.settings.hidden;render();markChanged('Layer visibility updated');});action(n.settings.locked?'Unlock':'Lock','Toggle lock',()=>{checkpoint();n.settings.locked=!n.settings.locked;render();markChanged('Layer lock updated');});wrap.appendChild(row);panel.appendChild(wrap);if(n.children&&(!collapsedLayers.has(n.id)||search))build(n.children,depth+1);});build(doc.nodes,0);if(!panel.children.length)panel.textContent=search?'No matching layers.':'No elements yet.';renderLayerNavigator();}
  function applyPreviewDevice(){const widths={desktop:'1200px',tablet:responsiveBreakpoints.tablet+'px',mobile:responsiveBreakpoints.mobile+'px'};canvas.dataset.previewDevice=previewDevice;canvas.style.width=widths[previewDevice];canvas.style.maxWidth='100%';document.querySelectorAll('[data-preview-device]').forEach(button=>{const active=button.dataset.previewDevice===previewDevice;button.classList.toggle('button-primary',active);button.setAttribute('aria-pressed',active?'true':'false');});}
 function render(){ensureDefaultSection();renderCanvasOnly();settings();renderLayers();updateHistoryButtons();}
 function renderCanvasOnly(){applyPreviewDevice();canvas.replaceChildren();canvas.classList.toggle('nb-wireframe',wireframe);doc.nodes.forEach(n=>canvas.appendChild(nodeView(n,0)));}
 async function loadLibrary(){const target=document.getElementById('nirmaan-library-list');if(!target)return;target.replaceChildren();try{const items=await api('library');items.filter(item=>Number(item.id)!==Number(cfg.libraryId)).forEach(item=>{const b=document.createElement('button');b.type='button';b.className='button';b.textContent=(item.global?'◆ ':'')+'Insert: '+item.title;b.onclick=()=>{if(item.global){const n=make('global_element');n.settings.library_id=item.id;doc.nodes.push(n);}else{doc.nodes.push(...(item.document.nodes||[]).map(n=>({...n,id:uid()})));}render();status(t('Unsaved changes'));};target.appendChild(b);});}catch(e){target.textContent=t('Library unavailable');}}
 async function load(){try{try{const siteSettings=await api('settings');if(siteSettings.breakpoints)responsiveBreakpoints={tablet:Number(siteSettings.breakpoints.tablet)||1024,mobile:Number(siteSettings.breakpoints.mobile)||767};}catch(e){}if(cfg.postId){const d=await api('content/'+cfg.postId);doc=d.document||{nodes:[]};}else if(cfg.libraryId){const d=await api('library/'+cfg.libraryId);doc=d.document||{nodes:[]};}else{const d=await api('templates/'+cfg.templateId);doc=d.parts?.[cfg.part]||{nodes:[]};}render();undoStack.length=0;redoStack.length=0;updateHistoryButtons();loaded=true;let recovery=null;try{const local=JSON.parse(localStorage.getItem(recoveryKey)||'null');if(local&&local.document)recovery={document:local.document,savedAt:Math.floor(local.savedAt/1000),source:'this browser'};}catch(e){}try{const remote=await api('autosave/'+targetType+'/'+targetId+'?part='+encodeURIComponent(part));if(remote.autosave&&(!recovery||remote.autosave.saved_at>recovery.savedAt))recovery={document:remote.autosave.document,savedAt:remote.autosave.saved_at,source:'server'};}catch(e){}if(recovery&&confirm('A recoverable unsaved draft from '+recovery.source+' was found. Restore it?')){doc=recovery.document;render();status(t('Recovered draft — save to publish these changes'));}ensureDefaultSection();render();loadLibrary();}catch(e){status(e.message);}}
 let canvasZoom=100;
 const zoomLabel=document.getElementById('nb-canvas-zoom-value');
 const setZoom=value=>{canvasZoom=Math.max(50,Math.min(150,Number(value)||100));canvas.style.zoom=canvasZoom+'%';if(zoomLabel)zoomLabel.textContent=canvasZoom+'%';};
 document.getElementById('nb-zoom-out')?.addEventListener('click',()=>setZoom(canvasZoom-10));
 document.getElementById('nb-zoom-in')?.addEventListener('click',()=>setZoom(canvasZoom+10));
 document.getElementById('nb-zoom-reset')?.addEventListener('click',()=>setZoom(100));
 const fullscreenButton=document.getElementById('nb-editor-fullscreen');
 const editorWrap=document.querySelector('.nirmaan-editor-wrap');
 const setFullscreen=active=>{editorWrap?.classList.toggle('nb-editor-fullscreen',active);document.body.classList.toggle('nb-editor-active',active);if(fullscreenButton){fullscreenButton.textContent=active?'Exit Fullscreen':'Fullscreen';fullscreenButton.setAttribute('aria-pressed',active?'true':'false');}};
 setFullscreen(true);
 fullscreenButton?.addEventListener('click',()=>setFullscreen(!editorWrap?.classList.contains('nb-editor-fullscreen')));
 document.getElementById('nb-editor-context-menu')?.addEventListener('click',e=>e.stopPropagation());document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeSettings();}});
 document.addEventListener('click',closeContextMenu);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeContextMenu();if(editorWrap?.classList.contains('nb-editor-fullscreen'))setFullscreen(false);}});
 const layerSearch=document.getElementById('nb-layer-search');layerSearch?.addEventListener('input',renderLayers);document.getElementById('nb-layer-expand-all')?.addEventListener('click',()=>{const visit=nodes=>nodes.forEach(n=>{if(n.children){collapsedLayers.delete(n.id);visit(n.children);}});visit(doc.nodes);renderLayers();});document.getElementById('nb-layer-collapse-all')?.addEventListener('click',()=>{const visit=nodes=>nodes.forEach(n=>{if(n.children){collapsedLayers.add(n.id);visit(n.children);}});visit(doc.nodes);renderLayers();});
 const viewButton=document.getElementById('nirmaan-view-toggle');if(viewButton)viewButton.onclick=()=>{wireframe=!wireframe;viewButton.textContent=wireframe?'Visual View':'Wireframe View';canvas.classList.toggle('nb-wireframe',wireframe);};
 document.querySelectorAll('[data-preview-device]').forEach(button=>button.addEventListener('click',()=>{previewDevice=button.dataset.previewDevice;render();}));
 const undoButton=document.getElementById('nirmaan-undo');if(undoButton)undoButton.onclick=undo;const redoButton=document.getElementById('nirmaan-redo');if(redoButton)redoButton.onclick=redo;
 document.addEventListener('keydown',e=>{const tag=(e.target&&e.target.tagName||'').toLowerCase();if(['input','textarea','select'].includes(tag)||e.target?.isContentEditable)return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.shiftKey&&e.key.toLowerCase()==='c'){e.preventDefault();if(copyStyles()){render();status(t('Styles copied'));}return;}if(mod&&e.shiftKey&&e.key.toLowerCase()==='v'){e.preventDefault();pasteStyles();return;}if(mod&&e.key.toLowerCase()==='c'&&selected){e.preventDefault();const source=find(selected);if(source){nodeClipboard=clone(source.node);status(t('Element copied'));}return;}if(mod&&e.key.toLowerCase()==='v'&&nodeClipboard){e.preventDefault();const copy=rekey(clone(nodeClipboard));checkpoint();const target=selected&&find(selected);if(target&&target.node.children)target.node.children.push(copy);else doc.nodes.push(copy);selectNode(copy.id);render();markChanged('Element pasted');return;}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return;}if(mod&&e.key.toLowerCase()==='d'&&selected){e.preventDefault();duplicateNode(selected);return;}if((e.key==='Delete'||e.key==='Backspace')&&selected){e.preventDefault();deleteNode(selected);}});
 canvas.addEventListener('dragover',e=>{if(e.target===canvas)e.preventDefault();});
 canvas.addEventListener('drop',e=>{if(e.target!==canvas)return;e.preventDefault();const source=find(e.dataTransfer.getData('text/plain'));if(!source)return;checkpoint();const moved=source.nodes.splice(source.index,1)[0];doc.nodes.push(moved);selectNode(moved.id);render();markChanged('Element moved to canvas root');});
 document.getElementById('nirmaan-save').onclick=async()=>{closeSettings();if(saving)return;saving=true;clearTimeout(autosaveTimer);const snapshot=clone(doc);try{status(t('Saving…'));await autosaveInFlight.catch(()=>{});if(cfg.postId)await api('content/'+cfg.postId,{method:'POST',body:JSON.stringify(snapshot)});else if(cfg.libraryId)await api('library/'+cfg.libraryId,{method:'POST',body:JSON.stringify({document:snapshot})});else await api('templates/'+cfg.templateId,{method:'POST',body:JSON.stringify({part:cfg.part,document:snapshot})});if(JSON.stringify(doc)===JSON.stringify(snapshot)){await api('autosave/'+targetType+'/'+targetId+'?part='+encodeURIComponent(part),{method:'DELETE'});try{localStorage.removeItem(recoveryKey);}catch(e){}dirty=false;status(t('Saved'));}else{dirty=true;status(t('Saved; newer edits are still pending'));}}catch(e){dirty=true;status('Save failed: '+e.message);}finally{saving=false;if(dirty)scheduleAutosave();}};
 const revisionsButton=document.getElementById('nirmaan-revisions');if(revisionsButton)revisionsButton.onclick=async()=>{try{const result=await api('revisions/'+targetType+'/'+targetId+'?part='+encodeURIComponent(part));const revisions=result.revisions||[];if(!revisions.length){alert(t('No saved revisions yet.'));return;}const choice=prompt('Enter revision number to restore:\n'+revisions.map((r,i)=>(i+1)+'. '+r.created_at+' (by user '+r.author+')').join('\n'));if(choice===null)return;const index=Number(choice)-1;if(!Number.isInteger(index)||!revisions[index]){alert(t('Invalid revision number.'));return;}if(!confirm(t('Restore this revision? Current changes will remain available as a revision.')))return;const restored=await api('revisions/'+targetType+'/'+targetId,{method:'POST',body:JSON.stringify({revision_id:revisions[index].revision_id,part})});checkpoint();doc=restored.document;selected=null;selectedIds=new Set();render();markChanged('Revision restored — save to apply it');}catch(e){alert('Could not load revisions: '+e.message);}};
 const saveLib=document.getElementById('nirmaan-save-library');if(saveLib)saveLib.onclick=async()=>{const picked=selectedNodes();const nodes=picked.length?picked:[...doc.nodes];if(!nodes.length){alert(t('Add or select elements before saving to the Library.'));return;}const title=prompt(picked.length>1?'Name this reusable section:':'Name this reusable item:');if(!title||!title.trim())return;const category=prompt('Library type: section, template, module-preset or layout',''+(picked.length>1?'section':'module-preset'));if(category===null)return;const allowed=['section','template','module-preset','layout'];const type=allowed.includes(category.trim().toLowerCase())?category.trim().toLowerCase():'layout';const global=confirm(t('Make this a Global Element? Linked instances will reflect later Library edits.'));const savedDoc={nodes:nodes.map(node=>rekey(clone(node)))};try{await api('library',{method:'POST',body:JSON.stringify({title:title.trim(),document:savedDoc,global,category:type})});status((global?'Global element':'Reusable '+type)+' saved to Library');loadLibrary();}catch(e){alert('Could not save to Library: '+e.message);}};
 const exportBtn=document.getElementById('nirmaan-export-library');if(exportBtn)exportBtn.onclick=async()=>{try{const data=await api('library/export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='nirmaan-builder-library.json';a.click();URL.revokeObjectURL(a.href);}catch(e){alert(e.message);}};
 const importInput=document.getElementById('nirmaan-import-library');if(importInput)importInput.onchange=async()=>{const file=importInput.files[0];if(!file)return;try{const data=JSON.parse(await file.text());const result=await api('library/import',{method:'POST',body:JSON.stringify(data)});alert('Imported '+result.imported+' layouts');loadLibrary();}catch(e){alert('Import failed: '+e.message);}finally{importInput.value='';}};
 load();
